<?php
declare(strict_types=1);session_start();require __DIR__.'/config.php';require dirname(__DIR__).'/api/bootstrap.php';
if(isset($_GET['logout'])){session_destroy();header('Location: index.php');exit;}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['maintenance_code'])){if(hash_equals(GPME_MAINTENANCE_CODE,(string)$_POST['maintenance_code']))$_SESSION['gpme_maint']=true;else $error='Code incorrect.';}
$authed=!empty($_SESSION['gpme_maint']);
if($authed&&$_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['action'],$_POST['id'])){try{$db=gpme_db();$id=(int)$_POST['id'];if($_POST['action']==='treated'){$st=$db->prepare("UPDATE feedback SET status='treated',updated_at=CURRENT_TIMESTAMP WHERE id=?");$st->execute([$id]);}elseif($_POST['action']==='pending'){$st=$db->prepare("UPDATE feedback SET status='pending',updated_at=CURRENT_TIMESTAMP WHERE id=?");$st->execute([$id]);}elseif($_POST['action']==='delete'){$st=$db->prepare('DELETE FROM feedback WHERE id=?');$st->execute([$id]);}header('Location: index.php');exit;}catch(Throwable $e){$error=$e->getMessage();}}
$rows=[];$pending=0;if($authed){try{$db=gpme_db();$rows=$db->query("SELECT * FROM feedback ORDER BY CASE WHEN status='pending' THEN 0 ELSE 1 END, created_at DESC")->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $r)if($r['status']!=='treated')$pending++;}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Maintenance — BTS GPME</title><link rel="stylesheet" href="../assets/app-v41.css"><style>body{font-family:system-ui,sans-serif;background:#f7f8fc;color:#2f3b59}.maint{max-width:1180px;margin:2rem auto;padding:1rem}.maint-card{background:#fff;border:1px solid #e2e6ef;border-radius:16px;padding:1.2rem;box-shadow:0 10px 30px rgba(50,60,100,.07)}.maint table{width:100%;border-collapse:collapse;font-size:.9rem}.maint th,.maint td{border-bottom:1px solid #e7eaf1;text-align:left;padding:.7rem;vertical-align:top}.maint th{color:#69748d;font-size:.76rem;text-transform:uppercase;letter-spacing:.05em}.status{display:inline-block;border-radius:999px;padding:.25rem .5rem;font-size:.72rem;font-weight:800}.pending{background:#ffe8ed;color:#b23d58}.treated{background:#e8f6ee;color:#3a855e}.actions{display:flex;gap:.35rem;flex-wrap:wrap}.actions button,.maint a.btn{border:0;border-radius:8px;padding:.45rem .6rem;text-decoration:none;font:inherit;font-size:.8rem;cursor:pointer;background:#eef1f7;color:#52607a}.actions button[name="action"][value="delete"]{color:#b13e54}.login{max-width:430px;margin:8rem auto}.login input{width:100%;padding:.7rem;border:1px solid #dce1eb;border-radius:10px;margin:.5rem 0}.login button{border:0;background:#5f73e7;color:#fff;border-radius:10px;padding:.65rem .9rem;font-weight:750}</style></head><body><main class="maint"><?php if(!$authed):?><section class="maint-card login"><h1>Maintenance</h1><p>Les contenus d’apprentissage restent accessibles sans connexion. Ce code protège seulement les actions de traitement et de suppression des retours.</p><?php if($error):?><p style="color:#b23d58"><?=htmlspecialchars($error)?></p><?php endif?><form method="post"><label>Code de maintenance<input type="password" name="maintenance_code" autofocus required></label><button type="submit">Accéder</button></form><p><a href="../index.html">← Retour à l’accueil</a></p></section><?php else:?><header style="display:flex;justify-content:space-between;align-items:end;gap:1rem;margin-bottom:1rem"><div><p style="margin:0;color:#77829a">BTS GPME</p><h1 style="margin:.2rem 0">Maintenance <span class="status pending"><?=$pending?> à traiter</span></h1><p>Consulter, traiter ou supprimer les demandes d’amélioration.</p></div><div><a class="btn" href="export.php">Exporter CSV</a> <a class="btn" href="?logout=1">Quitter</a></div></header><?php if($error):?><p class="maint-card" style="color:#b23d58"><?=htmlspecialchars($error)?></p><?php endif?><section class="maint-card"><table><thead><tr><th>État</th><th>Ressource</th><th>Type</th><th>Commentaire</th><th>Date</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><span class="status <?=htmlspecialchars($r['status'])?>"><?=$r['status']==='treated'?'Traité':'À traiter'?></span></td><td><strong><?=htmlspecialchars($r['resource_title'])?></strong><br><small><?=htmlspecialchars($r['resource_id'])?><?= $r['section']?' · '.htmlspecialchars($r['section']):'' ?></small></td><td><?=htmlspecialchars($r['category'])?></td><td><?=nl2br(htmlspecialchars($r['comment']))?></td><td><?=htmlspecialchars($r['created_at'])?></td><td><form class="actions" method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><?php if($r['status']==='treated'):?><button name="action" value="pending">Remettre à traiter</button><?php else:?><button name="action" value="treated">Marquer traité</button><?php endif?><button name="action" value="delete" onclick="return confirm('Supprimer définitivement ce retour ?')">Supprimer</button></form></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="6">Aucun retour enregistré.</td></tr><?php endif?></tbody></table></section><p><a href="../index.html">← Retour à l’application</a></p><?php endif?></main></body></html>